// 안전한 헬퍼 함수
export function getConvictionList(locale: string = 'ko'): ConvictionListItem[] {
  return convictionListsByLocale[locale] || convictionListsByLocale['en'] || convictionListsByLocale['ko'] || []
}

export function getConvictionsPageUi(locale: string = 'ko'): ConvictionsPageUi {
  return convictionsPageUiByLocale[locale] || convictionsPageUiByLocale['en'] || convictionsPageUiByLocale['ko']
}
